  protected override void Initialize() {
    this.InitSpecialTokens((int)Tokens.error, (int)Tokens.EOF);
    this.InitStates(states);
    this.InitRules(rules);
    this.InitNonTerminals(nonTerms);
  }

  protected override void DoAction(int action)
  {
    switch (action)
    {
      case 2: // program -> import_clause, decl_and_stmt_list, optional_semicolon
{
		var ul = ValueStack[ValueStack.Depth-3].stn as uses_list;
		var stl = ValueStack[ValueStack.Depth-2].stn as statement_list;
		stl.left_logical_bracket = new token_info("");
		stl.right_logical_bracket = new token_info("");
		var bl = new block(decl, stl, LocationStack[LocationStack.Depth-2]);
		decl.AddFirst(decl_forward.defs);
		root = CurrentSemanticValue.stn = NewProgramModule(null, null, ul, bl, ValueStack[ValueStack.Depth-1].ob, CurrentLocationSpan);
		root.source_context = bl.source_context;
	}
        break;
      case 3: // program -> MOD, ident, SEMICOLON, import_clause, decl_and_stmt_list
{
		decl.AddFirst(decl_forward.defs);
		var interface_part = new interface_node(decl as declarations, ValueStack[ValueStack.Depth-2].stn as uses_list, null, null);
		var initialization_part = new initfinal_part(null, ValueStack[ValueStack.Depth-1].stn as statement_list, null, null, null, CurrentLocationSpan);

		root = CurrentSemanticValue.stn = new unit_module(
			new unit_name(new ident(ValueStack[ValueStack.Depth-4].id.name),
			UnitHeaderKeyword.Unit, CurrentLocationSpan), interface_part, null,
			initialization_part.initialization_sect,
			initialization_part.finalization_sect, null, CurrentLocationSpan);
	}
        break;
      case 4: // import_clause -> /* empty */
{ CurrentSemanticValue.stn = null; }
        break;
      case 5: // import_clause -> import_clause, import_clause_one
{
		if (parserTools.build_tree_for_formatter) {
			if (ValueStack[ValueStack.Depth-2].stn == null) {	
				CurrentSemanticValue.stn = new uses_closure(ValueStack[ValueStack.Depth-1].stn as uses_list,CurrentLocationSpan);
			} else {
			    (ValueStack[ValueStack.Depth-2].stn as uses_closure).AddUsesList(ValueStack[ValueStack.Depth-1].stn as uses_list,CurrentLocationSpan);
			    CurrentSemanticValue.stn = ValueStack[ValueStack.Depth-2].stn;
			}
		} else {
			if (ValueStack[ValueStack.Depth-2].stn == null) {
			    CurrentSemanticValue.stn = ValueStack[ValueStack.Depth-1].stn;
			    CurrentSemanticValue.stn.source_context = CurrentLocationSpan;
			} else {
			    (ValueStack[ValueStack.Depth-2].stn as uses_list).AddUsesList(ValueStack[ValueStack.Depth-1].stn as uses_list,CurrentLocationSpan);
			    CurrentSemanticValue.stn = ValueStack[ValueStack.Depth-2].stn;
			    CurrentSemanticValue.stn.source_context = CurrentLocationSpan;
			}
		}
		}
        break;
      case 6: // import_clause_one -> USE, ident, SEMICOLON
{
			CurrentSemanticValue.stn = new uses_list(new unit_or_namespace(new ident_list(ValueStack[ValueStack.Depth-2].id as ident, LocationStack[LocationStack.Depth-2]), LocationStack[LocationStack.Depth-2]),LocationStack[LocationStack.Depth-2]);
			CurrentSemanticValue.stn.source_context = CurrentLocationSpan;
			}
        break;
      case 7: // decl_or_stmt -> stmt
{ CurrentSemanticValue.stn = ValueStack[ValueStack.Depth-1].stn; }
        break;
      case 8: // decl_or_stmt -> decl
{ CurrentSemanticValue.stn = null; }
        break;
      case 9: // decl -> proc_func_decl
{
		CurrentSemanticValue.stn = null;
		decl.Add(ValueStack[ValueStack.Depth-1].stn as procedure_definition, CurrentLocationSpan);
	}
        break;
      case 10: // decl_and_stmt_list -> decl_or_stmt
{
			if (ValueStack[ValueStack.Depth-1].stn is statement st)
				CurrentSemanticValue.stn = new statement_list(ValueStack[ValueStack.Depth-1].stn as statement, LocationStack[LocationStack.Depth-1]);
			else
				CurrentSemanticValue.stn =  new statement_list();
			}
        break;
      case 11: // decl_and_stmt_list -> decl_and_stmt_list, decl_or_stmt
{
			if (ValueStack[ValueStack.Depth-1].stn is statement st)
				CurrentSemanticValue.stn = (ValueStack[ValueStack.Depth-2].stn as statement_list).Add(st, CurrentLocationSpan);
			else
				CurrentSemanticValue.stn = (ValueStack[ValueStack.Depth-2].stn as statement_list);
			}
        break;
      case 12: // stmt_list -> stmt
{
			CurrentSemanticValue.stn = new statement_list(ValueStack[ValueStack.Depth-1].stn as statement, LocationStack[LocationStack.Depth-1]);
		}
        break;
      case 13: // stmt_list -> stmt_list, stmt
{
			CurrentSemanticValue.stn = (ValueStack[ValueStack.Depth-2].stn as statement_list).Add(ValueStack[ValueStack.Depth-1].stn as statement, CurrentLocationSpan);
		}
        break;
      case 14: // stmt -> assign_stmt, SEMICOLON
{ CurrentSemanticValue.stn = ValueStack[ValueStack.Depth-2].stn; }
        break;
      case 15: // stmt -> block
{ CurrentSemanticValue.stn = ValueStack[ValueStack.Depth-1].stn; }
        break;
      case 16: // stmt -> var_stmt, SEMICOLON
{ CurrentSemanticValue.stn = ValueStack[ValueStack.Depth-2].stn; }
        break;
      case 17: // stmt -> if_stmt
{ CurrentSemanticValue.stn = ValueStack[ValueStack.Depth-1].stn; }
        break;
      case 18: // stmt -> proc_func_call_stmt, SEMICOLON
{ CurrentSemanticValue.stn = ValueStack[ValueStack.Depth-2].stn; }
        break;
      case 19: // stmt -> while_stmt
{ CurrentSemanticValue.stn = ValueStack[ValueStack.Depth-1].stn; }
        break;
      case 20: // stmt -> for_stmt
{ CurrentSemanticValue.stn = ValueStack[ValueStack.Depth-1].stn; }
        break;
      case 21: // stmt -> return_stmt, SEMICOLON
{ CurrentSemanticValue.stn = ValueStack[ValueStack.Depth-2].stn; }
        break;
      case 22: // stmt -> break_stmt, SEMICOLON
{ CurrentSemanticValue.stn = ValueStack[ValueStack.Depth-2].stn; }
        break;
      case 23: // stmt -> continue_stmt, SEMICOLON
{ CurrentSemanticValue.stn = ValueStack[ValueStack.Depth-2].stn; }
        break;
      case 24: // ident -> ID
{
			if (ValueStack[ValueStack.Depth-1].id.name == "result")
				ValueStack[ValueStack.Depth-1].id.name = "%result";

			CurrentSemanticValue.id = ValueStack[ValueStack.Depth-1].id;
		}
        break;
      case 25: // var_stmt -> LET, variable, COLON, simple_type_identifier, ASSIGN, expr
{
			var vds = new var_def_statement(new ident_list(ValueStack[ValueStack.Depth-5].ex as ident, LocationStack[LocationStack.Depth-5]), ValueStack[ValueStack.Depth-3].td, ValueStack[ValueStack.Depth-1].ex, definition_attribute.None, false, CurrentLocationSpan);

			if (ValueStack[ValueStack.Depth-5].ex is ident id && ScopeCounter == 0 && !globalVariables.Contains(id.name)) {
					globalVariables.Add(id.name);
					CurrentSemanticValue.stn = new assign(id as addressed_value, ValueStack[ValueStack.Depth-1].ex, ValueStack[ValueStack.Depth-2].op.type, CurrentLocationSpan);
					decl.Add(new variable_definitions(vds, CurrentLocationSpan), CurrentLocationSpan);
			}
			else
				CurrentSemanticValue.stn = new var_statement(vds, CurrentLocationSpan);
		}
        break;
      case 26: // assign_stmt -> LET, variable, ASSIGN, expr
{
			var ass = new assign(ValueStack[ValueStack.Depth-3].ex as addressed_value, ValueStack[ValueStack.Depth-1].ex, ValueStack[ValueStack.Depth-2].op.type, CurrentLocationSpan);

			if (ValueStack[ValueStack.Depth-3].ex is ident id && ScopeCounter == 0 && !globalVariables.Contains(id.name)) {
				globalVariables.Add(id.name);
				ass.first_assignment_defines_type = true;
				type_definition ntr = new named_type_reference(new ident("integer"));
				var vds = new var_def_statement(new ident_list(id, LocationStack[LocationStack.Depth-4]), ntr, null, definition_attribute.None, false, CurrentLocationSpan);
				decl.Add(new variable_definitions(vds, CurrentLocationSpan), CurrentLocationSpan);
			}
			
			CurrentSemanticValue.stn = ass;

			/*if ($2 is ident id) {
				// об�?явление
				if (!isInsideFunction && ($3 != null || (!symbolTable.Contains(id.name) && (isInsideFunction || !globalVariables.Contains(id.name))))) {

					// об�?явление глобал�?ной пе�?еменной
					if (symbolTable.OuterScope == null) {
						if (globalVariables.Contains(id.name)) {
							parserTools.AddErrorFromResource("This variable is declared before", @$);
						}
						else {
							var ass = new assign(id as addressed_value, $4, $3.type, @$);
							globalVariables.Add(id.name);

							type_definition ntr;

							if ($3 == null) {
								ntr = new named_type_reference(new ident("integer"));
								// ntr = (new same_type_node($4) as type_definition);
								ass.first_assignment_defines_type = true;
							}
							else ntr = $3 as type_definition;

							var vds = new var_def_statement(new ident_list(id, @1), ntr, null, definition_attribute.None, false, @$);
							decl.Add(new variable_definitions(vds, @$), @$);
							$$ = ass;
						}
					}
					// об�?явление локал�?ной пе�?еменной
					else {
						var vds = new var_def_statement(new ident_list(id, @1), $3, $4, definition_attribute.None, false, @$);
						symbolTable.Add(id.name);
						$$ = new var_statement(vds, @$);
					}
				}
				// п�?исваивание
				else {
					$$ = new assign(id as addressed_value, $4, $3.type, @$);
				}
			}
			else {
				$$ = new assign($2 as addressed_value, $4, $3.type, @$);
			}*/
		}
        break;
      case 27: // assign_stmt -> variable, assign_type, expr
{
			if (!(ValueStack[ValueStack.Depth-3].ex is addressed_value))
        		parserTools.AddErrorFromResource("LEFT_SIDE_CANNOT_BE_ASSIGNED_TO",CurrentLocationSpan);
			CurrentSemanticValue.stn = new assign(ValueStack[ValueStack.Depth-3].ex as addressed_value, ValueStack[ValueStack.Depth-1].ex, ValueStack[ValueStack.Depth-2].op.type, CurrentLocationSpan);
		}
        break;
      case 28: // assign_type -> PLUSEQUAL
{ CurrentSemanticValue.op = ValueStack[ValueStack.Depth-1].op; }
        break;
      case 29: // assign_type -> MINUSEQUAL
{ CurrentSemanticValue.op = ValueStack[ValueStack.Depth-1].op; }
        break;
      case 30: // assign_type -> STAREQUAL
{ CurrentSemanticValue.op = ValueStack[ValueStack.Depth-1].op; }
        break;
      case 31: // assign_type -> DIVEQUAL
{ CurrentSemanticValue.op = ValueStack[ValueStack.Depth-1].op; }
        break;
      case 32: // expr -> expr, PLUS, expr
{ CurrentSemanticValue.ex = new bin_expr(ValueStack[ValueStack.Depth-3].ex, ValueStack[ValueStack.Depth-1].ex, ValueStack[ValueStack.Depth-2].op.type, CurrentLocationSpan); }
        break;
      case 33: // expr -> expr, STAR, expr
{ CurrentSemanticValue.ex = new bin_expr(ValueStack[ValueStack.Depth-3].ex, ValueStack[ValueStack.Depth-1].ex, ValueStack[ValueStack.Depth-2].op.type, CurrentLocationSpan); }
        break;
      case 34: // expr -> expr, DIVIDE, expr
{ CurrentSemanticValue.ex = new bin_expr(ValueStack[ValueStack.Depth-3].ex, ValueStack[ValueStack.Depth-1].ex, ValueStack[ValueStack.Depth-2].op.type, CurrentLocationSpan); }
        break;
      case 35: // expr -> expr, MINUS, expr
{ CurrentSemanticValue.ex = new bin_expr(ValueStack[ValueStack.Depth-3].ex, ValueStack[ValueStack.Depth-1].ex, ValueStack[ValueStack.Depth-2].op.type, CurrentLocationSpan); }
        break;
      case 36: // expr -> expr, LESS, expr
{ CurrentSemanticValue.ex = new bin_expr(ValueStack[ValueStack.Depth-3].ex, ValueStack[ValueStack.Depth-1].ex, ValueStack[ValueStack.Depth-2].op.type, CurrentLocationSpan); }
        break;
      case 37: // expr -> expr, GREATER, expr
{ CurrentSemanticValue.ex = new bin_expr(ValueStack[ValueStack.Depth-3].ex, ValueStack[ValueStack.Depth-1].ex, ValueStack[ValueStack.Depth-2].op.type, CurrentLocationSpan); }
        break;
      case 38: // expr -> expr, LESSEQUAL, expr
{ CurrentSemanticValue.ex = new bin_expr(ValueStack[ValueStack.Depth-3].ex, ValueStack[ValueStack.Depth-1].ex, ValueStack[ValueStack.Depth-2].op.type, CurrentLocationSpan); }
        break;
      case 39: // expr -> expr, GREATEREQUAL, expr
{ CurrentSemanticValue.ex = new bin_expr(ValueStack[ValueStack.Depth-3].ex, ValueStack[ValueStack.Depth-1].ex, ValueStack[ValueStack.Depth-2].op.type, CurrentLocationSpan); }
        break;
      case 40: // expr -> expr, EQUAL, expr
{ CurrentSemanticValue.ex = new bin_expr(ValueStack[ValueStack.Depth-3].ex, ValueStack[ValueStack.Depth-1].ex, ValueStack[ValueStack.Depth-2].op.type, CurrentLocationSpan); }
